/*selectMasterWmstNoticeList*/
SELECT BID, BTYPE, DECODE(COMPANY, 'KRKORE0001', '전체',TRIM(REPLACE(REPLACE(UPPER(REPLACE((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = COMPANY), '코리아이플랫폼(주)', '')), 'HUB센터', ''), '_',''))) AS COM_NAME, SUBSTRB(SUBJECT,1,60) SUBJECT, REG_USER_NAME, REG_DATE, ACL, LCOUNT, BLEVEL, VID, DECODE(ACL,'INC','자사', 'BUY','구매사', 'SEL', '판매사', 'KEP','KEP','MEB','회원전체','CST','특정회사','UST','특정사용자','ALL','전체') ACL_DIS, IMAGE_KEY FROM ICOMBOARD WHERE STATUS <>'D' AND FROM_DATE <= TO_CHAR(SYSDATE, 'YYYYMMDD') AND TO_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDD') AND BTYPE = 'WM' AND OPEN_FLAG = 'Y' AND (COMPANY = 'KRKORE0001'
OR COMPANY = (SELECT TEXT1 AS WAREHOUSE_CODE FROM ICOMCOD2 WHERE TYPE = 'WR01' AND FLAG = 'Y' AND COMPANY_CODE = #{st_com_code} AND CODE = #{st_user_id})
) ORDER BY REG_DATE DESC , VID DESC
